  presentations.append({'id':id,'group':group,'name':name,'explanation':ex,'course':'Often improves over several weeks with a manageable, consistent routine. Persistent symptoms can still improve; progress is not always linear.' if id!='frozen-shoulder' else 'Often changes over many months. Comfort and useful movement matter more than forcing range.','helps':'Start with a dose you can recover from. Use the next-morning response to guide load, then build strength gradually.','nameAr':{'lower-back':'نمط ألم أسفل الظهر','neck':'نمط ألم الرقبة','shoulder':'نمط ألم الكتف','knee':'نمط ألم الركبة','hip':'نمط ألم الورك','ankle':'نمط ألم الكاحل','elbow':'نمط ألم الذراع','upper-back':'نمط ألم أعلى الظهر'}[group]})
  rules.append({'presentationId':id,'group':group,'baseScore':3 if i==0 else 1,'aggravators':{a:4 for a in agg},'easers':{a:3 for a in ease},'neuroWeight':7 if 'radicular' in id or id=='carpal-tunnel' else -1,'gradualWeight':4 if id=='frozen-shoulder' else 0,'incidentWeight':5 if id in ['ankle-sprain','groin-strain','meniscal'] else 0})
