 y={'forehead':1.72,'jaw':1.6,'neck':1.49,'shoulder':1.43,'upper-arm':1.26,'chest':1.3,'upper-back':1.3,'elbow':1.1,'forearm':.96,'wrist':.84,'hand':.72,'abdomen':1.12,'lower-back':1.12,'hip':.9,'thigh':.68,'knee':.48,'calf':.3,'ankle':.12,'foot':.04}[part]
